#![cfg(feature = "unstable-dynamic")]

use clap_complete::engine::complete;
use std::ffi::OsString;
use std::path::Path;

fn run(cmd: &mut clap::Command, input: &str) -> Vec<String> {
    let mut args = vec![OsString::from("exhaustive")];
    let mut words: Vec<&str> = input.split_whitespace().collect();
    let cur = if words.last() == Some(&"[TAB]") {
        words.pop().unwrap();
        args.push(OsString::new());
        words.len()
    } else {
        panic!("need [TAB]");
    };
    args.extend(words.iter().map(OsString::from));
    let current_dir: Option<&Path> = None;
    match complete(cmd, args, cur, current_dir) {
        Ok(cs) => cs
            .into_iter()
            .map(|c| format!("{}\t{}", c.get_value(), c.get_help().unwrap_or_default()))
            .collect(),
        Err(e) => vec![format!("ERR: {e}")],
    }
}

#[test]
fn scratch_eq() {
    let mut cmd = clap::Command::new("exhaustive")
        .arg(
            clap::Arg::new("safe")
                .long("safe")
                .action(clap::ArgAction::SetTrue),
        )
        .arg(
            clap::Arg::new("fast")
                .long("fast")
                .short('f')
                .visible_alias("quick")
                .alias("speedy")
                .action(clap::ArgAction::SetTrue)
                .conflicts_with("safe"),
        )
        .arg(
            clap::Arg::new("tag")
                .long("tag")
                .short('t')
                .value_parser(["red", "blue"])
                .conflicts_with("fast"),
        );

    for input in [
        "--tag=red [TAB]",
        "--tag=r [TAB]",
        "--tag= [TAB]",
        "--tag=red -- [TAB]",
        "--fast=true [TAB]",
        "--tag=red -f [TAB]",
    ] {
        println!("INPUT: {input}");
        for line in run(&mut cmd, input) {
            println!("  {line}");
        }
    }
}

