pub(crate) fn assert_matches(
    expected: impl IntoData,
    generator: impl clap_complete::Generator,
    mut cmd: clap::Command,
    name: &'static str,
) {
    let mut buf = vec![];
    clap_complete::generate(generator, &mut cmd, name, &mut buf);

