                )
            })
            .collect(),
        Err(e) => vec![format!("ERR: {e}")],
    }
}

fn conflict_cmd() -> clap::Command {
    clap::Command::new("exhaustive")
        .arg(
            clap::Arg::new("safe")
                .long("safe")
                .action(clap::ArgAction::SetTrue),
        )
        .arg(
            clap::Arg::new("fast")
                .long("fast")
                .short('f')
                .visible_alias("quick")
                .alias("speedy")
                .action(clap::ArgAction::SetTrue)
                .conflicts_with("safe"),
        )
        .arg(
            clap::Arg::new("tag")
                .long("tag")
                .short('t')
                .value_parser(["red", "blue"])
                .conflicts_with("fast"),
        )
}

#[test]
fn scratch_eq() {
    let mut cmd = conflict_cmd();
    for input in [
        // closed --name=value before cursor, then empty new word
        "--tag=red [TAB]",
        // in-word value completion
        "--tag=r[TAB]",
        "--tag=[TAB]",
        // after --
        "--tag=red -- [TAB]",
        // no-value option with = (error semantics: keep existing)
        "--fast=true [TAB]",
        // unknown long with =
        "--unknown=x [TAB]",
        // prefix completion of disabled option
        "--tag=red --f[TAB]",
        "--tag=red --q[TAB]",
        // value candidates of disabled option via current word
        "--tag=red --fast=[TAB]",
        // value that looks like an option must not be misparsed
        "--tag=--safe [TAB]",
        "--tag=--fast [TAB]",
        // both present explicitly
        "--tag=red --fast [TAB]",
    ] {
        println!("INPUT: {input}");
        for line in run(&mut cmd, input) {
            println!("  {line}");
        }
    }
}

