                .long("safe")
                .action(clap::ArgAction::SetTrue),
        )
        .arg(
            clap::Arg::new("fast")
                .long("fast")
                .short('f')
                .visible_alias("quick")
                .alias("speedy")
                .action(clap::ArgAction::SetTrue)
                .conflicts_with("safe"),
        )
        .arg(
            clap::Arg::new("tag")
                .long("tag")
                .short('t')
                .value_parser(["red", "blue"])
                .conflicts_with("fast"),
        );

    for input in [
        "--tag=red [TAB]",
        "--tag=r[TAB]",
        "--tag=[TAB]",
        "--tag=red -- [TAB]",
        "--fast=true [TAB]",
        "--tag=red -f [TAB]",
        "--tag=red --f[TAB]",
        "--tag=red --fast [TAB]",
    ] {
        println!("INPUT: {input}");
        for line in run(&mut cmd, input) {
            println!("  {line}");
        }
    }
}

