#![cfg(feature = "unstable-dynamic")]

use clap_complete::engine::complete;
use std::ffi::OsString;
use std::path::Path;

fn run(cmd: &mut clap::Command, input: &str) -> String {
    let mut args = vec![OsString::from(cmd.get_name())];
    let (prior, _after) = input.split_once("[TAB]").expect("need [TAB]");
    args.extend(prior.split_whitespace().map(OsString::from));
    if prior.ends_with(char::is_whitespace) {
        args.push(OsString::new());
    }
    let cur = args.len() - 1;
    let current_dir: Option<&Path> = None;
    match complete(cmd, args, cur, current_dir) {
        Ok(cs) => cs
            .into_iter()
            .map(|c| {
                format!(
                    "{}",
                    c.get_value().to_string_lossy(),
                )
            })
            .collect::<Vec<_>>()
            .join(","),
        Err(e) => format!("ERR: {e}"),
    }
}

#[test]
fn cases() {
    // Delimiter + conflict
    let mut cmd = clap::Command::new("exhaustive")
        .arg(
            clap::Arg::new("list")
                .long("list")
                .value_parser(["a", "b", "c"])
                .value_delimiter(',')
                .num_args(1..=3)
                .conflicts_with("fast"),
        )
        .arg(
            clap::Arg::new("fast")
                .long("fast")
                .short('f')
                .action(clap::ArgAction::SetTrue),
        );
    for input in [
        "--list=a,b [TAB]",
        "--list=a,b --f[TAB]",
        "--list=a,b -f[TAB]",
        "--list=a,b -[TAB]",
    ] {
        println!("{input} => {}", run(&mut cmd, input));
    }

    // multi-value (no delimiter), attached then following
    let mut cmd2 = clap::Command::new("exhaustive")
        .arg(
            clap::Arg::new("multi")
                .long("multi")
                .value_parser(["a", "b", "c"])
                .num_args(1..=3)
                .conflicts_with("fast"),
        )
        .arg(
            clap::Arg::new("fast")
                .long("fast")
                .short('f')
                .action(clap::ArgAction::SetTrue),
        );
    for input in ["--multi=a [TAB]", "--multi=a --f[TAB]", "--multi=a -f[TAB]"] {
        println!("{input} => {}", run(&mut cmd2, input));
    }

    // invalid/impossible attached value still records name -> suppresses
    let mut cmd3 = clap::Command::new("exhaustive")
        .arg(
            clap::Arg::new("tag")
                .long("tag")
                .value_parser(["red", "blue"])
                .conflicts_with("fast"),
        )
        .arg(
            clap::Arg::new("fast")
                .long("fast")
                .short('f')
                .action(clap::ArgAction::SetTrue),
        );
    for input in ["--tag=zzz [TAB]", "--tag=zzz --f[TAB]"] {
        println!("{input} => {}", run(&mut cmd3, input));
    }

    // group: value-taking member conflicts via group
    let mut cmd4 = clap::Command::new("exhaustive")
        .arg(
            clap::Arg::new("tag")
                .long("tag")
                .value_parser(["red", "blue"]),
        )
        .arg(
            clap::Arg::new("file")
                .long("file")
                .action(clap::ArgAction::SetTrue),
        )
        .arg(
            clap::Arg::new("fast")
                .long("fast")
                .short('f')
                .action(clap::ArgAction::SetTrue),
        )
        .group(
            clap::ArgGroup::new("payload")
                .args(["tag", "file"])
                .conflicts_with("fast"),
        );
    for input in [
        "--tag=red [TAB]",
        "--tag=red --f[TAB]",
        "--tag=red -f[TAB]",
        "--tag=red -[TAB]",
    ] {
        println!("{input} => {}", run(&mut cmd4, input));
    }

    // currently-edited equals word must not apply its own conflict early
    for input in ["--tag=[TAB]", "--tag=r[TAB]", "--fast=[TAB]"] {
        println!("EDIT {input} => {}", run(&mut cmd4.clone(), input));
    }
}

