        "--tag=r[TAB]",
        "--tag=[TAB]",
        // after --
        "--tag=red -- [TAB]",
        // no-value option with = (error semantics: keep existing)
        "--fast=true [TAB]",
        // unknown long with =
        "--unknown=x [TAB]",
        // prefix completion of disabled option
        "--tag=red --f[TAB]",
        "--tag=red --q[TAB]",
        // value candidates of disabled option via current word
        "--tag=red --fast=[TAB]",
