#![cfg(feature = "unstable-dynamic")]

use clap_complete::engine::complete;
use std::ffi::OsString;
use std::path::Path;

fn run_args(cmd: &mut clap::Command, args: Vec<OsString>, cur: usize) -> String {
    let current_dir: Option<&Path> = None;
    match complete(cmd, args, cur, current_dir) {
        Ok(cs) => cs
            .into_iter()
            .map(|c| format!("{}", c.get_value().to_string_lossy()))
            .collect::<Vec<_>>()
            .join(","),
        Err(e) => format!("ERR: {e}"),
    }
}

fn run(cmd: &mut clap::Command, input: &str) -> String {
    let mut args = vec![OsString::from(cmd.get_name())];
    let (prior, _after) = input.split_once("[TAB]").expect("need [TAB]");
    args.extend(prior.split_whitespace().map(OsString::from));
    if prior.ends_with(char::is_whitespace) {
        args.push(OsString::new());
    }
    let cur = args.len() - 1;
    run_args(cmd, args, cur)
}

#[test]
fn cases2() {
    // no_binary_name: first word is --tag=red
    let mut cmd = clap::Command::new("exhaustive")
        .no_binary_name(true)
        .arg(
            clap::Arg::new("tag")
                .long("tag")
                .value_parser(["red", "blue"])
                .conflicts_with("fast"),
        )
        .arg(
            clap::Arg::new("fast")
                .long("fast")
                .short('f')
                .action(clap::ArgAction::SetTrue),
        );
    println!(
        "nobin --tag=red '' => {}",
        run_args(
            &mut cmd,
            vec!["--tag=red".into(), "".into()],
            1
        )
    );
    println!(
        "nobin --tag=r => {}",
        run_args(&mut cmd, vec!["--tag=r".into()], 0)
    );

    // defaults / env must not count as explicit presence
    let mut cmd2 = clap::Command::new("exhaustive")
        .arg(
            clap::Arg::new("mode")
                .long("mode")
                .value_parser(["a", "b"])
                .default_value("a")
                .conflicts_with("fast"),
        )
        .arg(
            clap::Arg::new("fast")
                .long("fast")
                .short('f')
                .action(clap::ArgAction::SetTrue),
        );
    // mode has a default but was NOT typed: fast must still be offered
    println!("default-only [TAB] => {}", run(&mut cmd2, "[TAB]"));
    // typed --mode=b: fast suppressed
    println!("--mode=b [TAB] => {}", run(&mut cmd2, "--mode=b [TAB]"));

    let mut cmd3 = clap::Command::new("exhaustive")
        .arg(
            clap::Arg::new("mode")
                .long("mode")
                .value_parser(["a", "b"])
                .env("MODE")
                .conflicts_with("fast"),
        )
        .arg(
            clap::Arg::new("fast")
                .long("fast")
                .short('f')
                .action(clap::ArgAction::SetTrue),
        );
    // SAFETY: test process env
    unsafe { std::env::set_var("MODE", "a") };
    println!("env-only [TAB] => {}", run(&mut cmd3, "[TAB]"));
    unsafe { std::env::remove_var("MODE") };

    // require_equals option
    let mut cmd4 = clap::Command::new("exhaustive")
        .arg(
            clap::Arg::new("cfg")
                .long("cfg")
                .value_parser(["x", "y"])
                .require_equals(true)
                .conflicts_with("fast"),
        )
        .arg(
            clap::Arg::new("fast")
                .long("fast")
                .short('f')
                .action(clap::ArgAction::SetTrue),
        );
    println!("--cfg=x [TAB] => {}", run(&mut cmd4, "--cfg=x [TAB]"));
    println!("--cfg=[TAB] => {}", run(&mut cmd4, "--cfg=[TAB]"));

    // hidden option with equals
    let mut cmd5 = clap::Command::new("exhaustive")
        .arg(
            clap::Arg::new("secret")
                .long("secret")
                .hide(true)
                .value_parser(["s1", "s2"])
                .conflicts_with("fast"),
        )
        .arg(
            clap::Arg::new("fast")
                .long("fast")
                .short('f')
                .action(clap::ArgAction::SetTrue),
        );
    println!("--secret=s1 [TAB] => {}", run(&mut cmd5, "--secret=s1 [TAB]"));

    // visible alias with equals: --quick is alias of fast (SetTrue, conflicts safe)
    let mut cmd6 = clap::Command::new("exhaustive")
        .arg(
            clap::Arg::new("safe")
                .long("safe")
                .action(clap::ArgAction::SetTrue),
        )
        .arg(
            clap::Arg::new("fast")
                .long("fast")
                .visible_alias("quick")
                .action(clap::ArgAction::SetTrue)
                .conflicts_with("safe"),
        )
        .arg(
            clap::Arg::new("tag")
                .long("tag")
                .value_parser(["red", "blue"]),
        );
    println!("--quick [TAB] => {}", run(&mut cmd6, "--quick [TAB]"));
    println!("--tag=red --q[TAB] => {}", run(&mut cmd6, "--safe --q[TAB]"));
}

