#![cfg(feature = "unstable-dynamic")]

use clap_complete::engine::complete;
use std::ffi::OsString;
use std::path::Path;

fn run_args(cmd: &mut clap::Command, args: Vec<OsString>, cur: usize) -> String {
    let current_dir: Option<&Path> = None;
    match complete(cmd, args, cur, current_dir) {
        Ok(cs) => cs
            .into_iter()
            .map(|c| format!("{}", c.get_value().to_string_lossy()))
            .collect::<Vec<_>>()
            .join(","),
        Err(e) => format!("ERR: {e}"),
    }
}

fn run(cmd: &mut clap::Command, input: &str) -> String {
    let mut args = vec![OsString::from(cmd.get_name())];
    let (prior, _after) = input.split_once("[TAB]").expect("need [TAB]");
    args.extend(prior.split_whitespace().map(OsString::from));
    if prior.ends_with(char::is_whitespace) {
        args.push(OsString::new());
    }
    let cur = args.len() - 1;
    run_args(cmd, args, cur)
}

