#![cfg(feature = "unstable-dynamic")]

use clap_complete::engine::complete;
use std::ffi::OsString;
use std::path::Path;

fn run(cmd: &clap::Command, words: &[&str]) -> Result<Vec<String>, String> {
    let mut c = cmd.clone();
    let mut args = vec![OsString::from("exhaustive")];
    args.extend(words.iter().map(OsString::from));
    let cur = args.len() - 1;
    let current_dir: Option<&Path> = None;
    match complete(&mut c, args, cur, current_dir) {
        Ok(cs) => Ok(cs
            .into_iter()
            .map(|c| c.get_value().to_string_lossy().into_owned())
            .collect()),
        Err(e) => Err(e.to_string()),
    }
}

fn cmd() -> clap::Command {
    clap::Command::new("exhaustive")
        .arg(
            clap::Arg::new("safe")
                .long("safe")
                .short('s')
                .action(clap::ArgAction::SetTrue),
        )
        .arg(
            clap::Arg::new("fast")
                .long("fast")
                .short('f')
                .visible_alias("quick")
                .alias("speedy")
                .action(clap::ArgAction::SetTrue)
                .conflicts_with("safe"),
        )
        .arg(
            clap::Arg::new("tag")
                .long("tag")
                .short('t')
                .value_parser(["red", "blue"])
                .conflicts_with("fast"),
        )
        .arg(
            clap::Arg::new("color")
                .long("color")
                .value_parser(["red", "green", "blue"])
                .conflicts_with("fast"),
        )
}

#[test]
fn differential_attached_vs_separate() {
    let c = cmd();
    // (separate form words, attached form words) — last word is the edited word
    let pairs: &[(&[&str], &[&str])] = &[
        (&["--tag", "red", ""], &["--tag=red", ""]),
        (&["--tag", "red", "--"], &["--tag=red", "--"]),
        (&["-t", "red", ""], &["--tag=red", ""]),
        (&["--tag", "red", "-f"], &["--tag=red", "-f"]),
        (&["--tag", "red", "--fast="], &["--tag=red", "--fast="]),
        (&["--tag", "red", "--q"], &["--tag=red", "--q"]),
        (&["--tag", "red", "--spe"], &["--tag=red", "--spe"]),
        (&["--color", "red", ""], &["--color=red", ""]),
        (&["--color", "red", "-"], &["--color=red", "-"]),
        (&["--fast", "", "--safe"][..0], &[""][..0]),
    ];

    let mut failures = 0;
    for (i, (sep, att)) in pairs.iter().enumerate() {
        if sep.is_empty() {
            continue;
        }
        let a = run(&c, sep);
        let b = run(&c, att);
        let mark = if a == b { "OK " } else { "DIF" };
        println!("{mark} case {i}: sep={sep:?} att={att:?}");
        if a != b {
            failures += 1;
            println!("   separate: {a:?}");
            println!("   attached: {b:?}");
        }
    }
    assert_eq!(failures, 0);
}

