    let c = cmd();
    // (separate form words, attached form words) — last word is the edited word
    let pairs: &[(&[&str], &[&str])] = &[
        (&["--tag", "red", ""], &["--tag=red", ""]),
        (&["--tag", "red", "--"], &["--tag=red", "--"]),
        (&["-t", "red", ""], &["--tag=red", ""]),
        (&["--tag", "red", "-f"], &["--tag=red", "-f"]),
        (&["--tag", "red", "--fast="], &["--tag=red", "--fast="]),
        (&["--tag", "red", "--q"], &["--tag=red", "--q"]),
        (&["--tag", "red", "--spe"], &["--tag=red", "--spe"]),
        (&["--color", "red", ""], &["--color=red", ""]),
        (&["--color", "red", "-"], &["--color=red", "-"]),
        (&["--fast", "", "--safe"][..0], &[""][..0]),
    ];

    let mut failures = 0;
    for (i, (sep, att)) in pairs.iter().enumerate() {
        if sep.is_empty() {
            continue;
        }
        let a = run(&c, sep);
        let b = run(&c, att);
        let mark = if a == b { "OK " } else { "DIF" };
        println!("{mark} case {i}: sep={sep:?} att={att:?}");
        if a != b {
            failures += 1;
            println!("   separate: {a:?}");
            println!("   attached: {b:?}");
        }
    }
    assert_eq!(failures, 0);
}

