fn cases2() {
    // no_binary_name: first word is --tag=red
    let mut cmd = clap::Command::new("exhaustive")
        .no_binary_name(true)
        .arg(
            clap::Arg::new("tag")
                .long("tag")
                .value_parser(["red", "blue"])
                .conflicts_with("fast"),
        )
        .arg(
            clap::Arg::new("fast")
                .long("fast")
                .short('f')
                .action(clap::ArgAction::SetTrue),
        );
    println!(
        "nobin --tag=red '' => {}",
        run_args(
            &mut cmd,
            vec!["--tag=red".into(), "".into()],
            1
        )
    );
    println!(
        "nobin --tag=r => {}",
        run_args(&mut cmd, vec!["--tag=r".into()], 0)
    );

    // defaults / env must not count as explicit presence
    let mut cmd2 = clap::Command::new("exhaustive")
        .arg(
            clap::Arg::new("mode")
                .long("mode")
                .value_parser(["a", "b"])
                .default_value("a")
                .conflicts_with("fast"),
        )
        .arg(
            clap::Arg::new("fast")
                .long("fast")
                .short('f')
                .action(clap::ArgAction::SetTrue),
        );
