    println!("default-only [TAB] => {}", run(&mut cmd2, "[TAB]"));
    // typed --mode=b: fast suppressed
    println!("--mode=b [TAB] => {}", run(&mut cmd2, "--mode=b [TAB]"));

    // require_equals option
    let mut cmd4 = clap::Command::new("exhaustive")
        .arg(
