#[test]
fn suggest_conflicts_attached_long_value() {
    // A closed `--name=value` word before the cursor is parsed exactly like the
    // separate `--name value` form: the option name counts as present and the
    // attached value is consumed, never seen as another option or positional.
    fn command() -> Command {
        Command::new("exhaustive")
            .arg(
                clap::Arg::new("safe")
                    .long("safe")
                    .action(clap::ArgAction::SetTrue),
            )
            .arg(
                clap::Arg::new("fast")
                    .long("fast")
                    .short('f')
                    .visible_alias("quick")
                    .alias("speedy")
                    .action(clap::ArgAction::SetTrue)
                    .conflicts_with("safe"),
            )
            .arg(
                clap::Arg::new("tag")
                    .long("tag")
                    .short('t')
                    .value_parser(["red", "blue"])
                    .conflicts_with("fast"),
            )
    }

    // `--tag=red` before a fresh empty word: same result as `--tag red`.
    assert_data_eq!(
        complete!(command(), "--tag=red [TAB]"),
        snapbox::str![[r#"
--safe
--tag
--help	Print help
"#]],
    );

    // The conflict carries onto later options regardless of how they are typed.
    assert_data_eq!(complete!(command(), "--tag=red --f[TAB]"), snapbox::str![""]);
    assert_data_eq!(complete!(command(), "--tag=red --fast[TAB]"), snapbox::str![""]);
    assert_data_eq!(
        complete!(command(), "--tag=red -[TAB]"),
        snapbox::str![[r#"
-s	--safe
-t	--tag
-h	Print help
"#]],
    );
    // Visible and hidden aliases and the value candidates of `fast` vanish too.
    assert_data_eq!(complete!(command(), "--tag=red --q[TAB]"), snapbox::str![""]);
    assert_data_eq!(complete!(command(), "--tag=red --spe[TAB]"), snapbox::str![""]);
    assert_data_eq!(complete!(command(), "--tag=red --fast=[TAB]"), snapbox::str![""]);

    // A value attached through `=` that merely looks like an option belongs to
    // `tag`; it must not be parsed as `--safe`/`--fast`.
    assert_data_eq!(
        complete!(command(), "--tag=--safe [TAB]"),
        snapbox::str![[r#"
--safe
--tag
--help	Print help
"#]],
    );

    // Editing the value behind `=` follows the normal prefix rules and never
    // crosses the `=` to complete option names.
    assert_data_eq!(
        complete!(command(), "--tag=[TAB]"),
        snapbox::str![[r#"
--tag=red
--tag=blue
"#]],
    );
    assert_data_eq!(complete!(command(), "--tag=r[TAB]"), snapbox::str!["--tag=red"]);

    // The word under the cursor does not contribute conflict state yet: while
    // `--tag=` is edited, `fast` is not suppressed; while `--fast=` is edited on
    // a value-less flag, no candidates are guessed.
    assert_data_eq!(
        complete!(command(), "--tag=[TAB]extra"),
        snapbox::str![""]
    );
    assert_data_eq!(complete!(command(), "--fast=true [TAB]"), snapbox::str![[r#"
--fast
--help	Print help
"#]]);

    // An unknown long name keeps the existing (empty) error semantics.
    assert_data_eq!(complete!(command(), "--unknown=x [TAB]"), snapbox::str![[r#"
--fast
--safe
--tag
--help	Print help
"#]]);
}

