    assert_data_eq!(
        complete!(cmd, "--list=a,[TAB]"),
        snapbox::str![[r#"
--list=a,a
--list=a,b
--list=a,c
"#]],
    );

    // An attached value always closes the word, even for a multi-value option:
    // following words are options, and the conflict persists.
    let mut multi = Command::new("exhaustive")
        .arg(
            clap::Arg::new("multi")
                .long("multi")
                .value_parser(["a", "b", "c"])
