            clap::Arg::new("fast")
                .long("fast")
                .short('f')
                .action(clap::ArgAction::SetTrue),
        );
    assert_data_eq!(
        complete!(multi, "--multi=a [TAB]"),
        snapbox::str![[r#"
--multi
--help	Print help
"#]],
    );
    assert_data_eq!(complete!(multi, "--multi=a --f[TAB]"), snapbox::str![""]);
}

